-- ============================================================
-- Concussive Barrage: proc configuration
-- ============================================================
--
-- Core's -35100 row is replaced by two per-rank rows, because the 50/100%
-- split lives in spell_proc.Chance and that is keyed by spell id.
--
-- The family mask narrows to 4096 (Multi-Shot) alone.  Core's row also carries
-- SpellFamilyMask2 = 1 (Chimera Shot), which the redesign does not want --
-- Chimera Shot is a single-target finisher and already feeds Piercing Shots.
--
-- ProcFlags stays 0 so the DBC value carries through: SpellMgr::LoadSpellProcs
-- falls back to spellInfo->ProcFlags when the row is 0, and retail already
-- tuned those flags for exactly this ability.
--
-- NOTE the asymmetry with the buff: 200758 deliberately has NO spell_proc row
-- of its own.  Player::RemoveSpellMods skips any spellmod whose spell has a
-- proc entry (Player.cpp:10047), so giving 200758 one would stop its charge
-- ever being consumed and the buff would last its full 15s across many Volleys.
-- The charge comes from the DBC ProcCharges = 1 instead.

DELETE FROM `spell_proc` WHERE `SpellId` IN (-35100, 35100, 35102);
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(35100, 0, 9, 4096, 0, 0, 0, 0, 2, 0, 0, 0, 0, 50, 0, 0),
(35102, 0, 9, 4096, 0, 0, 0, 0, 2, 0, 0, 0, 0, 100, 0, 0);
